package com.codecircle.ws;
import com.codecircle.auth.JwtService;import org.springframework.context.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.socket.*;import org.springframework.web.socket.config.annotation.*;import org.springframework.web.socket.server.support.HttpSessionHandshakeInterceptor;import java.net.*;import java.util.*;
@Configuration @EnableWebSocket public class WebSocketConfig implements WebSocketConfigurer {final RoomWebSocketHandler handler;final JwtService jwt;WebSocketConfig(RoomWebSocketHandler h,JwtService j){handler=h;jwt=j;}public void registerWebSocketHandlers(WebSocketHandlerRegistry r){r.addHandler(handler,"/ws").setAllowedOriginPatterns("*").addInterceptors(new HttpSessionHandshakeInterceptor(){@Override public boolean beforeHandshake(org.springframework.http.server.ServerHttpRequest req,org.springframework.http.server.ServerHttpResponse res,WebSocketHandler h,Map<String,Object>a)throws Exception{Map<String,String>p=parse(req.getURI().getQuery());String token=p.get("token"),room=p.get("room"),name=p.get("name");if(token==null||room==null||name==null||room.length()!=6||!jwt.valid(token)){res.setStatusCode(HttpStatus.UNAUTHORIZED);return false;}String clean=room.toUpperCase().replaceAll("[^A-Z0-9]","");if(clean.length()!=6){res.setStatusCode(HttpStatus.BAD_REQUEST);return false;}a.put("room",clean);a.put("name",name.substring(0,Math.min(32,name.length())));a.put("user",jwt.username(token));return true;}});}
static Map<String,String>parse(String q){Map<String,String>m=new HashMap<>();if(q==null)return m;for(String x:q.split("&")){String[]p=x.split("=",2);if(p.length==2)m.put(p[0],URLDecoder.decode(p[1],java.nio.charset.StandardCharsets.UTF_8));}return m;}}
